class TestSymbolicStrategy:
    """Comprehensive tests for SymbolicStrategy.solve()."""

    def test_linear_equation(self, symbolic_strategy, linear_expression):
        """Solve 2x + 3 = 0 => x = -3/2."""
        expr, variables, expected = linear_expression
        result = symbolic_strategy.solve(expr, variables)
        assert result == [expected], f"Expected {expected}, got {result}"

    def test_quadratic_equation(self, symbolic_strategy, quadratic_expression):
        """Solve x^2 - 5x + 6 = 0 => x = [2, 3]."""
        expr, variables, expected = quadratic_expression
        result = symbolic_strategy.solve(expr, variables)
        assert sorted(result) == sorted(expected), f"Expected {expected}, got {result}"

    def test_cubic_equation(self, symbolic_strategy, cubic_expression):
        """Solve x^3 - 6x^2 + 11x - 6 = 0 => x = [1, 2, 3]."""
        expr, variables, expected = cubic_expression
        result = symbolic_strategy.solve(expr, variables)
        assert sorted(result) == sorted(expected), f"Expected {expected}, got {result}"

    def test_trigonometric_equation(self, symbolic_strategy, trigonometric_expression):
        """Solve sin(x) = 0 => x = 0 (principal)."""
        expr, variables, expected = trigonometric_expression
        result = symbolic_strategy.solve(expr, variables)
        assert expected in result, f"Expected {expected} in {result}"

    def test_exponential_equation(self, symbolic_strategy, exponential_expression):
        """Solve exp(x) - 1 = 0 => x = 0."""
        expr, variables, expected = exponential_expression
        result = symbolic_strategy.solve(expr, variables)
        assert expected in result, f"Expected {expected} in {result}"

    def test_no_real_solutions(self, symbolic_strategy, no_solution_expression):
        """x^2 + 1 = 0 should return imaginary solutions."""
        expr, variables, expected = no_solution_expression
        result = symbolic_strategy.solve(expr, variables)
        # Should contain imaginary unit
        assert any(sympy.I in sol.as_real_imag() for sol in result if hasattr(sol, 'as_real_imag'))

    def test_multi_variable_equation(self, symbolic_strategy, multi_variable_expression):
        """x + y - 5 = 0 should return a relationship."""
        expr, variables, _ = multi_variable_expression
        result = symbolic_strategy.solve(expr, variables)
        assert isinstance(result, list)
        assert len(result) > 0

    def test_empty_variables_list(self, symbolic_strategy):
        """Empty variables list should raise an error."""
        x = sympy.Symbol('x')
        expr = x**2 - 4
        with pytest.raises(Exception):
            symbolic_strategy.solve(expr, [])

    def test_constant_expression(self, symbolic_strategy):
        """5 = 0 should return empty list (no solutions)."""
        x = sympy.Symbol('x')
        expr = sympy.Integer(5)
        result = symbolic_strategy.solve(expr, [x])
        assert result == []

    def test_identity_expression(self, symbolic_strategy):
        """x - x = 0 should return True (always true)."""
        x = sympy.Symbol('x')
        expr = x - x
        result = symbolic_strategy.solve(expr, [x])
        # SymPy returns True for identities
        assert result == True or result == []

    def test_system_of_equations(self, symbolic_strategy):
        """Test solving a system: x + y = 5, x - y = 1."""
        x, y = sympy.symbols('x y')
        expr1 = x + y - 5
        expr2 = x - y - 1
        result = symbolic_strategy.solve([expr1, expr2], [x, y])
        assert {x: 3, y: 2} in result or result == [{x: 3, y: 2}]

    def test_rational_coefficients(self, symbolic_strategy):
        """Test with rational coefficients: (1/2)x + 3 = 0."""
        x = sympy.Symbol('x')
        expr = sympy.Rational(1, 2) * x + 3
        result = symbolic_strategy.solve(expr, [x])
        assert result == [sympy.Integer(-6)]

    def test_high_degree_polynomial(self, symbolic_strategy):
        """Test x^5 - 15x^4 + 85x^3 - 225x^2 + 274x - 120 = 0 (roots 1,2,3,4,5)."""
        x = sympy.Symbol('x')
        expr = x**5 - 15*x**4 + 85*x**3 - 225*x**2 + 274*x - 120
        result = symbolic_strategy.solve(expr, [x])
        expected = [1, 2, 3, 4, 5]
        assert sorted(result) == expected

    def test_invalid_expression_type(self, symbolic_strategy):
        """Non-sympy expression should raise error."""
        with pytest.raises(Exception):
            symbolic_strategy.solve("not an expression", [sympy.Symbol('x')])

    def test_none_variables(self, symbolic_strategy):
        """None variables should raise error."""
        x = sympy.Symbol('x')
        expr = x**2 - 4
        with pytest.raises(Exception):
            symbolic_strategy.solve(expr, None)

    def test_unsolvable_expression(self, symbolic_strategy):
        """Test expression that raises NotImplementedError."""
        x = sympy.Symbol('x')
        # Use a transcendental equation that SymPy cannot solve symbolically
        expr = sympy.sin(x) + sympy.log(x) - sympy.exp(x)
        with pytest.raises(NotImplementedError):
            symbolic_strategy.solve(expr, [x])


