class TestStrategyIntegration:
    """Tests that verify interaction between strategies and external components."""

    def test_both_strategies_same_linear(self, symbolic_strategy, numerical_strategy_default, linear_expression):
        """Both strategies should find the same root for linear equation."""
        expr, variables, _ = linear_expression
        symbolic_result = symbolic_strategy.solve(expr, variables)
        numerical_result = numerical_strategy_default.solve(expr, variables)
        # Symbolic returns list, numerical returns scalar
        assert any(abs(float(sol) - float(numerical_result)) < 1e-10 for sol in symbolic_result)

    def test_both_strategies_same_trigonometric(self, symbolic_strategy, numerical_strategy_default, trigonometric_expression):
        """Both strategies should find root near 0 for sin(x)."""
        expr, variables, _ = trigonometric_expression
        symbolic_result = symbolic_strategy.solve(expr, variables)
        numerical_result = numerical_strategy_default.solve(expr, variables)
        assert any(abs(float(sol) - float(numerical_result)) < 1e-10 for sol in symbolic_result if abs(float(sol)) < 1e-5)

    def test_strategy_pattern_compliance(self):
        """Verify both strategies follow the Strategy pattern correctly."""
        strategies = [SymbolicStrategy(), NumericalStrategy()]
        x = sympy.Symbol('x')
        expr = 2*x + 3
        
        for strategy in strategies:
            result = strategy.solve(expr, [x])
            assert result is not None, f"{type(strategy).__name__} returned None"


