class TestNumericalStrategyProperties:
    """Property-based tests for numerical stability and correctness."""

    def test_root_verification(self, numerical_strategy_default):
        """Property: f(solution) should be approximately zero."""
        import random
        x = sympy.Symbol('x')
        
        # Test with random linear equations
        for _ in range(10):
            a = random.uniform(-10, 10)
            b = random.uniform(-10, 10)
            if abs(a) < 1e-10:
                continue
            expr = a*x + b
            try:
                root = numerical_strategy_default.solve(expr, [x])
                # Verify f(root) ≈ 0
                f = sympy.lambdify(x, expr, 'mpmath')
                residual = abs(f(root))
                assert residual < 1e-8, f"Residual {residual} too large for {a}x + {b} = 0"
            except ConvergenceError:
                pass  # Some equations may not converge

    def test_solution_uniqueness(self, numerical_strategy_default):
        """Property: For linear equations, solution should be unique."""
        x = sympy.Symbol('x')
        for a, b in [(2, 3), (-5, 10), (0.5, -2), (100, -1000)]:
            expr = a*x + b
            root = numerical_strategy_default.solve(expr, [x])
            expected = -b/a
            assert abs(root - expected) < 1e-10


