class TestEdgeCases:
    """Tests for boundary conditions and unusual inputs."""

    def test_constant_zero_expression(self, numerical_strategy_default):
        """0 = 0 is always true - findroot may fail."""
        x = sympy.Symbol('x')
        expr = sympy.Integer(0)
        with pytest.raises((ConvergenceError, Exception)):
            numerical_strategy_default.solve(expr, [x])

    def test_very_flat_function(self, numerical_strategy_default):
        """Function that is nearly flat near root."""
        x = sympy.Symbol('x')
        expr = (x - 1)**100  # Very flat near x=1
        with pytest.raises((ConvergenceError, Exception)):
            numerical_strategy_default.solve(expr, [x])

    def test_multiple_roots_close_together(self, numerical_strategy_default):
        """Function with roots very close together."""
        x = sympy.Symbol('x')
        expr = (x - 1) * (x - 1.0001)  # Roots at 1 and 1.0001
        result = numerical_strategy_default.solve(expr, [x])
        # Should find one of the roots
        assert abs(result - 1) < 0.01 or abs(result - 1.0001) < 0.01

    def test_negative_precision(self):
        """Negative precision should be handled gracefully."""
        strategy = NumericalStrategy(precision=-10)
        assert strategy.precision == -10  # Stored as-is, but may cause issues

    def test_zero_precision(self):
        """Zero precision should be handled."""
        strategy = NumericalStrategy(precision=0)
        x = sympy.Symbol('x')
        expr = 2*x + 3
        with pytest.raises(Exception):
            strategy.solve(expr, [x])

    def test_very_high_precision(self):
        """Very high precision should not cause memory issues."""
        strategy = NumericalStrategy(precision=1000)
        x = sympy.Symbol('x')
        expr = 2*x + 3
        result = strategy.solve(expr, [x])
        assert abs(result - (-1.5)) < 1e-100


